#![cfg(feature = "corpus")]
//! Independent GIMP-authored source/edit PNG oracle, never generated by PhotoCraft.
use photocraft_algo::gimp::neighborhood::{GaussianAbyss, GaussianLimits, GaussianParams, try_gaussian_young, try_gaussian_young_recursive};
use photocraft_cms::{Builtin, Intent, Profile, Transform};
use photocraft_color::PixelFormat;
use photocraft_geom::Rect;
use photocraft_raster::{Interrupt, RasterInputError, Surface};
use std::path::PathBuf;

#[test]
fn authored_layer_gaussian_source_and_edit_match_existing_display_contract() {
    compare(try_gaussian_young);
}

#[test]
fn authored_direct_recursive_gaussian_source_and_edit_match_existing_display_contract() {
    compare(try_gaussian_young_recursive);
}

type Evaluator = fn(&Surface, Rect, Rect, GaussianParams, GaussianLimits, &Interrupt<'_>) -> Result<Surface, RasterInputError>;
fn compare(evaluate: Evaluator) {
    let root = std::env::var_os("PHOTOCRAFT_XCF_FULL_CORPUS")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../corpus/xcf/full"));
    assert!(root.is_dir(), "full XCF oracle corpus missing: set PHOTOCRAFT_XCF_FULL_CORPUS or stage corpus/xcf/full");
    let raw = std::fs::read(root.join("filter-owner-layer.source.0.native.bin")).unwrap();
    assert_eq!(raw.len(), 96 * 80 * 4);
    // Original source snapshots prove opaque literal RGBA and no source ICC override;
    // GIMP's export embeds the same implicit working ICC. Validate each source/edit
    // config envelope independently and use that PNG ICC for both directions.
    let state: serde_json::Value = serde_json::from_slice(&std::fs::read(root.join("filter-owner-layer.source_state.json")).unwrap()).unwrap();
    assert_eq!(state["precision"], "GIMP_PRECISION_U8_NON_LINEAR");
    assert_eq!(state["layers"][0]["filters"][0]["operation"], "gegl:gaussian-blur");
    assert!(raw.as_chunks::<4>().0.iter().all(|p| p[3] == 255));
    for (index, pixel) in raw.as_chunks::<4>().0.iter().enumerate() {
        let (x, y) = (index % 96, index / 96);
        let expected = if (7..36).contains(&x) && (9..32).contains(&y) { [208, 96, 48, 255] } else { [48, 80, 128, 255] };
        assert_eq!(*pixel, expected, "complete independent original literal rectangle must remain unchanged");
    }
    for (sigma, reference_name, state_name) in [
        (2.25, "filter-owner-layer.ref.png", "filter-owner-layer.reopened_state.json"),
        (3.75, "filter-owner-layer.edit.ref.png", "filter-owner-layer.edited_state.json"),
    ] {
        let state: serde_json::Value = serde_json::from_slice(&std::fs::read(root.join(state_name)).unwrap()).unwrap();
        let config = &state["layers"][0]["filters"][0]["config"];
        assert_eq!(config["std-dev-x"].as_f64(), Some(sigma));
        assert_eq!(config["std-dev-y"].as_f64(), Some(1.5));
        assert_eq!(config["filter"], "auto");
        assert_eq!(config["abyss-policy"], "clamp");
        assert_eq!(config["clip-extent"], true);
        let reference = photocraft_codecs::decode(&std::fs::read(root.join(reference_name)).unwrap()).unwrap();
        let icc = reference.icc.as_ref().expect("GIMP export must retain independent working ICC");
        let working = Profile::parse(icc).unwrap();
        let linear = Builtin::LinearSrgb.profile();
        let to_linear = Transform::new(&working, linear, Intent::RelativeColorimetric, false).unwrap();
        let from_linear = Transform::new(linear, &working, Intent::RelativeColorimetric, false).unwrap();
        let extent = Rect::new(0, 0, 96, 80);
        let mut samples = Vec::new();
        for pixel in raw.as_chunks::<4>().0.iter() {
            let input = [f64::from(pixel[0]) / 255.0, f64::from(pixel[1]) / 255.0, f64::from(pixel[2]) / 255.0];
            let mut output = [0.0; 3];
            to_linear.try_eval_f64(&input, &mut output).unwrap();
            samples.extend_from_slice(&output);
            samples.push(1.0);
        }
        let mut source = Surface::new(PixelFormat::RGBA64F);
        source.try_write_region_f64(extent, &samples).unwrap();
        let result = evaluate(
            &source,
            extent,
            extent,
            GaussianParams { std_dev_x: sigma, std_dev_y: 1.5, abyss: GaussianAbyss::Clamp, clip_extent: true },
            GaussianLimits::default(),
            &Interrupt::NONE,
        )
        .unwrap();
        let result = result.try_read_region_f64(extent).unwrap();
        let reference = reference.convert(photocraft_codecs::ChannelLayout::Rgba, photocraft_codecs::SampleType::U8);
        assert_eq!(reference.data().len(), 96 * 80 * 4);
        let mut worst = [0.0_f64; 4];
        let mut sums = [0.0_f64; 4];
        for (pixel, expected) in result.as_chunks::<4>().0.iter().zip(reference.data().as_chunks::<4>().0.iter()) {
            let mut encoded = [0.0; 3];
            from_linear.try_eval_f64(&pixel[..3], &mut encoded).unwrap();
            for channel in 0..4 {
                let actual = if channel == 3 { pixel[3] } else { encoded[channel] };
                let difference = (actual.clamp(0.0, 1.0) * 255.0 - f64::from(expected[channel])).abs();
                worst[channel] = worst[channel].max(difference);
                sums[channel] += difference;
            }
        }
        println!("{reference_name}: max8-bitcode={worst:?}, mean8-bitcode={:?}", sums.map(|v| v / (96.0 * 80.0)));
        assert!(worst.iter().all(|v| *v <= 2.0), "scoped authored Gaussian exceeds existing 2/255 display contract: {worst:?}");
    }
}
